-- Elemental Spell Magic: the complete Air, Earth, Fire and Water spell
-- lists (Rifts Book of Magic p.71-72), 231 rows.
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-elemental-spells.sql
--
-- NAMES ARE ELEMENT-QUALIFIED ("Air: Cloud of Steam") and that is load
-- bearing, not decoration. spells.name is UNIQUE, and these lists collide
-- two different ways:
--
--   - with the Invocation spells already in the catalog - Blinding Flash,
--     Globe of Daylight, Cloud of Smoke, Fire Bolt, Chameleon and Darkness
--     are all both, and an elemental Fire Bolt is not the invocation one;
--   - with EACH OTHER - Cloud of Steam is an Air 1st level (4 P.P.E.), a
--     Fire 4th level (10) and a Water 1st level (10). Freeze Water, Resist
--     Cold, Snow Storm, Hurricane, Circle of Rain, Heal Burns, Wall of Ice,
--     Drought, River of Lava, Frostblade, Dowsing and Protection from
--     Lightning all repeat across spheres at different levels and costs.
--
-- The prefix also groups the four spheres in the wizard's spell picker,
-- which filters by name substring: typing "Fire:" narrows to the Fire
-- sphere, which is how a Warlock picks from his own element.
--
-- Variable costs follow the ppe_note convention (migration 021): ppe holds
-- the MINIMUM, the note carries what the book prints - Create Wood
-- "5 or 10", Clay or Stone to Iron "40/60", Ironwood "50+".
--
-- Water prints Calm Waters TWICE, at 3rd level (15) and 8th (100); the
-- second is stored as "Water: Calm Waters (greater)" so both survive.
--
-- system is 'rifts'. Pure ASCII on purpose - see PR #101's pre-flight.

ON CONFLICT (name) DO NOTHING;

-- Read the result back rather than trusting the exit code.
SELECT COUNT(*) AS elemental_rows FROM spells WHERE source_book = 'Rifts Book of Magic p.71-72';
SELECT substr(name, 1, instr(name, ':') - 1) AS sphere, COUNT(*) AS n FROM spells
 WHERE source_book = 'Rifts Book of Magic p.71-72' GROUP BY sphere ORDER BY sphere;
SELECT name, level, ppe, ppe_note FROM spells WHERE name IN ('Air: Cloud of Steam', 'Fire: Cloud of Steam', 'Water: Cloud of Steam', 'Earth: Create Wood', 'Earth: Ironwood', 'Water: Calm Waters (greater)') ORDER BY name;
